219	// --- Transcript flush sentinel ---
220	
221	// stopHookSentinel is the string that appears in Claude Code's hook_progress
222	// entry when the stop hook has been invoked, indicating the transcript is fully flushed.
223	const stopHookSentinel = "hooks claude-code stop"
224	
225	// waitForTranscriptFlush polls the transcript file for the stop hook sentinel.
226	// Falls back silently after a timeout.
227	func waitForTranscriptFlush(ctx context.Context, transcriptPath string, hookStartTime time.Time) {
228		const (
229			maxWait      = 3 * time.Second
230			pollInterval = 50 * time.Millisecond
231			tailBytes    = 4096
232			maxSkew      = 2 * time.Second
233		)
234	
235		logCtx := logging.WithComponent(ctx, "agent.claudecode")
236	
237		// Fast path: skip the poll loop when the sentinel can't possibly appear.
238		// - File doesn't exist: nothing to poll.
239		// - File is stale (unmodified for 2+ min): agent isn't running anymore.
240		//   This avoids 3s timeouts per stale "active" session (e.g., agent crashed
241		//   without firing stop hook).
242		const staleThreshold = 2 * time.Minute
243		info, err := os.Stat(transcriptPath)
244		if err != nil {
245			// Most likely the file doesn't exist; other errors (permission, etc.)
246			// would also prevent polling, so skip the wait either way.
247			return
248		}
249		fileAge := time.Since(info.ModTime())
250		if fileAge > staleThreshold {
251			logging.Debug(logCtx, "transcript file is stale, skipping sentinel wait",
252				slog.Duration("file_age", fileAge),
253			)
254			return
255		}
256	
257		deadline := time.Now().Add(maxWait)
258		for time.Now().Before(deadline) {
259			if checkStopSentinel(transcriptPath, tailBytes, hookStartTime, maxSkew) {
260				logging.Debug(logCtx, "transcript flush sentinel found",
261					slog.Duration("wait", time.Since(hookStartTime)),
262				)
263				return
264			}
265			time.Sleep(pollInterval)
266		}
267		logging.Warn(logCtx, "transcript flush sentinel not found within timeout, proceeding",
268			slog.Duration("timeout", maxWait),
269		)
270	}
271	
272	// checkStopSentinel reads the tail of the transcript file and looks for the sentinel.
273	func checkStopSentinel(path string, tailBytes int64, hookStartTime time.Time, maxSkew time.Duration) bool {
274		f, err := os.Open(path) //nolint:gosec // path comes from agent hook input
275		if err != nil {
276			return false
277		}
278		defer f.Close()
279	
280		info, err := f.Stat()
281		if err != nil {
282			return false
283		}
284		offset := info.Size() - tailBytes
285		if offset < 0 {
286			offset = 0
287		}
288		buf := make([]byte, info.Size()-offset)
289		if _, err := f.ReadAt(buf, offset); err != nil {
290			return false
291		}
292	
293		lines := strings.Split(string(buf), "\n")
294		for _, line := range lines {
295			line = strings.TrimSpace(line)
296			if line == "" || !strings.Contains(line, stopHookSentinel) {
297				continue
298			}
299	
300			var entry struct {
301				Timestamp string `json:"timestamp"`
302			}
303			if json.Unmarshal([]byte(line), &entry) != nil || entry.Timestamp == "" {
304				continue
305			}
306			ts, err := time.Parse(time.RFC3339Nano, entry.Timestamp)
307			if err != nil {
308				ts, err = time.Parse(time.RFC3339, entry.Timestamp)
309				if err != nil {
310					continue
311				}
312			}
313			// Validate timestamp is within acceptable range:
314			// - Not too far in the past (before hook started minus skew)
315			// - Not too far in the future (after hook started plus skew)
316			lowerBound := hookStartTime.Add(-maxSkew)
317			upperBound := hookStartTime.Add(maxSkew)
318			if ts.After(lowerBound) && ts.Before(upperBound) {
319				return true
320			}
321		}
322		return false
323	}

