1464→// resolveFilesTouched returns the file list for a session.
1465→// Prefers hook-populated state.FilesTouched, falls back to transcript extraction.
1466→// All call sites that need "what files did the agent touch?" should use this.
1467→//
1468→// Handles PrepareTranscript internally before falling back to extraction,
1469→// so callers don't need to prepare the transcript first.
1470→func (s *ManualCommitStrategy) resolveFilesTouched(ctx context.Context, state *SessionState) []string {
1471→	var tracked []string
1472→	if store, err := s.getStateStore(ctx); err == nil {
1473→		tracked, _ = store.ReadFilesTouched(ctx, state.SessionID) //nolint:errcheck // Best-effort read, falls back to transcript
1474→	}
1475→
1476→	if len(state.FilesTouched) > 0 || len(tracked) > 0 {
1477→		seen := make(map[string]struct{})
1478→		var result []string
1479→		for _, f := range state.FilesTouched {
1480→			if _, ok := seen[f]; !ok {
1481→				seen[f] = struct{}{}
